isBlocked(name: string): boolean {
  const labels = labelsOf(name); // split ONCE
  let node = this.root;
  for (let i = labels.length - 1; i >= 0; i--) {
    const next = node.children.get(labels[i]!); // one Map.get per label
    if (!next) return false;
    node = next;
    if (node.blocked) return true;
  }
  return false;
}

